/**
 * ASCII progress rendering (graph runtime v2).
 *
 * Event-to-string rendering is pure so tests pin exact strings; the reporter
 * adds exactly one side effect per event — a single out.write of the rendered
 * line plus newline. No colors, no console.*, pure ASCII output.
 */

import type { ProgressReporter, RuntimeProgressEvent } from "./types.js";

/** Minimal writable surface shared by process.stdout and stream.PassThrough. */
type WriteSink = { write(chunk: string): unknown };

type NodeResultOutcome = Extract<
  RuntimeProgressEvent,
  { type: "node_result" }
>["outcome"];

/** node_result outcome -> ASCII tag. */
const OUTCOME_TAGS: Record<NodeResultOutcome, string> = {
  succeeded: "ok",
  failed: "fail",
  approved: "approved",
  denied: "denied",
  join_resolved: "join",
};

/** Renders one progress event as its exact ASCII line. Pure. */
export function renderProgressEvent(event: RuntimeProgressEvent): string {
  switch (event.type) {
    case "run_started":
      return `[run] ${event.run_id} — ${event.goal}`;
    case "replayed":
      return `[replay] ${event.records} record(s) @ epoch ${event.epoch}`;
    case "activation_started":
      return `[node] ${event.node_id} attempt #${event.attempt_no} started`;
    case "node_result":
      return `[${OUTCOME_TAGS[event.outcome]}] ${event.node_id}`;
    case "run_ended":
      return `[done] ${event.terminal} — ${event.summary}`;
  }
}

/**
 * ProgressReporter writing rendered lines to the given sink (default
 * process.stdout), one write per event.
 */
export function createAsciiProgressReporter(out?: WriteSink): ProgressReporter {
  const sink = out ?? process.stdout;
  return {
    onEvent(event: RuntimeProgressEvent): void {
      sink.write(`${renderProgressEvent(event)}\n`);
    },
  };
}

import { createMemo } from "solid-js"
import { DialogSelect } from "@tui/ui/dialog-select"
import { useDialog, type DialogContext } from "@tui/ui/dialog"
import { useLocal } from "@tui/context/local"
import { useLanguage } from "@tui/context/language"
import { useToast } from "../ui/toast"

const TIERS: (number | null)[] = [null, 30_000, 60_000, 120_000, 300_000, 600_000]

export function DialogPermissionTimeout() {
  const dialog = useDialog()
  const local = useLocal()
  const toast = useToast()
  const t = useLanguage().t

  const options = createMemo(() => {
    const current = local.permissionAskTimeout.current()
    const values =
      current !== null && !TIERS.includes(current) ? [current, ...TIERS] : TIERS
    return values.map((value) => ({
      title: value === null ? t("tui.permission_timeout.option.never") : formatDuration(value),
      value,
      description:
        value === null
          ? t("tui.permission_timeout.option.never_description")
          : t("tui.permission_timeout.option.tier_description", { duration: formatDuration(value) }),
    }))
  })

  return (
    <DialogSelect<number | null>
      title={t("tui.permission_timeout.title")}
      hint={t("tui.permission_timeout.hint")}
      options={options()}
      current={local.permissionAskTimeout.current()}
      onSelect={(option) => {
        local.permissionAskTimeout.set(option.value)
        toast.show({
          variant: "success",
          message:
            option.value === null
              ? t("tui.permission_timeout.toast_never")
              : t("tui.permission_timeout.toast_set", { duration: formatDuration(option.value) }),
          duration: 3000,
        })
        dialog.clear()
      }}
    />
  )
}

function formatDuration(ms: number): string {
  if (ms < 60_000) return `${Math.round(ms / 1000)}s`
  const minutes = Math.round(ms / 60_000)
  return `${minutes}min`
}

DialogPermissionTimeout.show = (dialog: DialogContext) => {
  dialog.replace(() => <DialogPermissionTimeout />)
}

import { readFile } from "fs/promises"
import { join } from "path"
import { homedir } from "os"

const MAX_BYTES = 25_000
const TRUNCATION_MARKER =
  "\n\n> WARNING: loop.md was truncated to 25000 bytes. Keep the task list concise."

export type LoopFileResult = { path: string; content: string }

/**
 * Read loop.md from project (.mimocode/loop.md) or home (~/loop.md). Project
 * takes precedence. Content > 25 KB is truncated with a warning marker.
 * Returns null when neither path exists or can be read.
 */
export const readLoopFile = async (workspaceRoot: string): Promise<LoopFileResult | null> => {
  const candidates = [join(workspaceRoot, ".mimocode", "loop.md"), join(homedir(), "loop.md")]
  for (const path of candidates) {
    const raw = await readFile(path, "utf-8").catch(() => null)
    if (raw === null) continue
    if (raw.length > MAX_BYTES) return { path, content: raw.slice(0, MAX_BYTES) + TRUNCATION_MARKER }
    return { path, content: raw }
  }
  return null
}
